INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 18, 'theory', 'Quiz: special methods');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 0, 'What really happens when you call len(obj)?', '["Python counts the object''s attributes", "Python reads obj.__dict__", "Python calls type(obj).__len__(obj)", "Python calls obj.length()"]', 2, 'The built-in function is just a facade: the interpreter finds the __len__ method on the object''s type and calls it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 1, 'What will print(obj) show if the class has both __str__ and __repr__?', '["The result of __repr__", "The result of __str__", "Both strings in a row", "The result of __format__"]', 1, 'print and f-strings use __str__; __repr__ is used by the console, the contents of lists, and !r.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 2, 'You wrote __eq__ but did not write __hash__. What happens to the object?', '["The hash is computed from id, as before", "Python raises an error when the class is defined", "The hash is taken from the result of __eq__", "The object becomes unhashable: it cannot go into a set or be a dict key"]', 3, 'Equal objects must have equal hashes, so when __eq__ is defined Python sets __hash__ to None on its own.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 3, 'What should __lt__ return if it cannot compare with a foreign type?', '["NotImplemented", "False", "None", "Raise ValueError"]', 0, 'NotImplemented gives Python a chance to try the reflected operation of the second operand; after that it raises TypeError itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 4, 'When is __getattr__ called?', '["On every access to any attribute", "Only when the ordinary lookup did not find the name", "When an attribute is written", "When the object is created"]', 1, '__getattr__ is a fallback after a failed lookup; __getattribute__ is the one called on every access.');
